import math

class Shape:
    def getArea(self):
        return 0

    def name(self):
        return "图形"


class Circle(Shape):
    def __init__(self, r):
        self.r = r

    def getArea(self):
        return math.pi * self.r ** 2

    def name(self):
        return "圆"


class Rectangle(Shape):
    def __init__(self, w, h):
        self.w = w
        self.h = h

    def getArea(self):
        return self.w * self.h

    def name(self):
        return "矩形"


def show(g):
    print("{} 的面积 = {:.2f}".format(g.name(), g.getArea()))


show(Shape())
show(Circle(1))
show(Rectangle(2, 4))


class Person:
    def name(self):
        return "路人甲"

    def getArea(self):
        return 1.75


show(Person())
print("Person 是 Shape 的子类吗? {}".format(issubclass(Person, Shape)))

